from boltons.cacheutils import cachedmethod, LRI
shared = LRI()
class Foo:
    @cachedmethod(shared)
    def method(self, x):
        return (id(self), x)

f1 = Foo()
f2 = Foo()
r1 = f1.method(1)
r2 = f2.method(1)
print(r1, r2)
print('BUG: same result across different instances!' if r1 == r2 else 'OK: differ')

class Lowerer:
    def __init__(self):
        self.cache = LRI()

    @cachedmethod('cache')
    def lower(self, text):
        return text.lower()

l = Lowerer()
print(l.lower('ABC'))
print(l.lower('ABC'))
print(len(l.cache))
print(l.cache)

# test scoped=False behavior - different methods sharing a cache entry if same args
class Bar:
    @cachedmethod(shared, scoped=False)
    def method1(self, x):
        return 'm1-' + str(x)
    @cachedmethod(shared, scoped=False)
    def method2(self, x):
        return 'm2-' + str(x)

b = Bar()
print(b.method1(5))
print(b.method2(5))  # should hit same cache entry as method1(5) since scoped=False and same args
"
